const roleInfo={S:['主語','だれ・何が'],V:['動詞','動作・存在'],O:['目的語','何を・だれを'],C:['補語','何であるか'],Adj:['状態','どんな状態か'],Adv:['程度・様態','どのくらい・どう'],T:['時間','いつ'],Loc:['場所','どこ・どこへ'],Aux:['助動詞','希望・可能・必要'],Neg:['否定','〜ない'],Q:['疑問','質問する印'],N:['名詞','もの・人'],Num:['数','いくつ'],Clf:['類別詞','数える単位'],Asp:['相・経験','完了・進行・経験'],Part:['助詞','語気・働きを添える'],Link:['接続','内容・節をつなぐ'],Comp:['比較','比べる相手'],Cond:['条件','もし〜なら'],Result:['結果','その結果どうなる'],Rel:['修飾節','どんな名詞か'],IO:['受益者','だれのために'],Clause:['内容節','文のまとまり']};
const structures=[
['S + V + O','「だれが → する → 何を」の順。会話ではSを省くことがあります。',[['S','ผม'],['V','กิน'],['O','ข้าว']]],
['T + Adj + Adv','状態を表すAdjは、そのまま述語になります。この例はSを省略。',[['T','วันนี้'],['Adj','ร้อน'],['Adv','มาก']]],
['V + N + Adj + Loc + Q','名詞Nの後ろからAdjで説明。例文は「ある＋店＋おいしい＋この辺＋？」。',[['V','มี'],['N','ร้าน'],['Adj','อร่อย'],['Loc','แถวนี้'],['Q','ไหม']]],
['S + เป็น + C','属性はS＋เป็น＋C。特定・同定にはคือを使います。',[['S','ผม'],['V','เป็น'],['C','คนญี่ปุ่น']]],
['S + อยู่ + Loc / มี + N','居場所はS＋อยู่＋Loc。存在・所有はมี＋N。',[['S','ผม'],['V','อยู่'],['Loc','ที่โรงงาน']]],
['(S) + Neg + V / Adj','否定のไม่は、動作や状態の前へ。この例は時間Tを先に置きます。',[['T','วันนี้'],['Neg','ไม่'],['Adj','ว่าง']]],
['(S) + V / Adj + Q','疑問のไหม（mǎi）は文の後ろ。例文の述語は状態Adj。',[['T','พรุ่งนี้'],['Adj','ว่าง'],['Q','ไหม']]],
['(S) + Aux + V + Q(O)','何を？のอะไรは目的語Oの位置へ。Q(O)は「目的語を聞く疑問詞」。',[['Aux','อยาก'],['V','กิน'],['Q','อะไร']]],
['(S) + V + O₁ + หรือ + O₂','選択はA＋หรือ＋B。確認なら文末にใช่ไหม（châi mǎi）。',[['V','เอา'],['O','ชา'],['Link','หรือ'],['O','กาแฟ']]],
['(S) + V + N + Num + Clf','名詞 → 数 → 類別詞。全体が動詞Vの目的語Oになります。',[['V','เอา'],['N','กาแฟ'],['Num','สอง'],['Clf','แก้ว']]],
['T + (S) + Aux + V + Loc','予定のจะはVの前。括弧の(S)は、この例で省略された主語です。',[['T','พรุ่งนี้'],['Aux','จะ'],['V','ไป'],['Loc','กรุงเทพ']]],
['(S) + กำลัง + V + O + อยู่','進行を表すกำลังは前、อยู่は動作句の後。',[['Asp','กำลัง'],['V','กิน'],['O','ข้าว'],['Asp','อยู่']]],
['(S) + V + O + แล้ว','แล้วは動作句・状態の後ろに置きます。',[['V','กิน'],['O','ข้าว'],['Asp','แล้ว']]],
['(S) + ยัง + Neg + V','まだ未実現ならยัง＋ไม่＋V。',[['Asp','ยัง'],['Neg','ไม่'],['V','เสร็จ']]],
['(S) + เคย + V + Loc + Q','経験のเคยはVの前。否定ならไม่เคย。',[['Asp','เคย'],['V','ไป'],['Loc','เชียงใหม่'],['Q','ไหม']]],
['(S) + Aux + V + Loc','希望のอยากはVの前。物が欲しい場合はอยากได้＋N。',[['Aux','อยาก'],['V','กลับ'],['Loc','บ้าน']]],
['(S) + V + ได้ / เป็น','可能・技能の表現はVの後ろ。この例ではไม่ได้で実行できない。',[['T','วันนี้'],['V','ไป'],['Neg','ไม่'],['Aux','ได้']]],
['T + (S) + Aux + V','必要のต้อง・助言のควรはVの前。',[['T','พรุ่งนี้'],['Aux','ต้อง'],['V','ทำงาน']]],
['ช่วย + V + Adv + หน่อย','依頼のช่วยとหน่อยで動作を挟みます。',[['Part','ช่วย'],['V','พูด'],['Adv','ช้า ๆ'],['Part','หน่อย']]],
['ลอง + V + O + ดู','ลอง＋動作＋ดูで「試してみる」。',[['Part','ลอง'],['V','ถาม'],['O','คนอื่น'],['Part','ดู']]],
['S + Adj + กว่า + Comp','状態 → กว่า→ 比較相手の順。',[['S','รถไฟฟ้า'],['Adj','เร็ว'],['Link','กว่า'],['Comp','แท็กซี่']]],
['結果 + เพราะ + 理由','เพราะは理由を導きます。ก็เลยは原因から結果へ。',[['Result','ไปไม่ได้'],['Link','เพราะ'],['Clause','ต้องทำงาน']]],
['ถ้า + Cond + ก็ + Result','ถ้าで条件、ก็で結果へ。ก็は省略する場合も。',[['Link','ถ้า'],['Cond','ว่าง'],['Link','ก็'],['Result','ไปด้วยกัน']]],
['N + ที่ + Rel → S / O','名詞Nをที่＋説明節Relで修飾。そのまとまりが文のSやOになります。',[['N','ร้าน'],['Link','ที่'],['Rel','ไปเมื่อวาน'],['Adj','อร่อย'],['Adv','มาก']]],
['(S) + V + ว่า + 内容節','คิดやบอกの内容をว่าでつなぎます。',[['V','คิด'],['Link','ว่า'],['Clause','พรุ่งนี้จะว่าง']]],
['(S) + V + O + ให้ + IO','してあげる：V＋ให้＋受益者IO。させる：ให้＋S＋V。',[['V','ซื้อ'],['O','ขนม'],['Link','ให้'],['IO','เพื่อน']]],
['原因節 + ทำให้ + 結果節','ทำให้が原因と結果をつなぎます。',[['Clause','ฝนตก'],['Link','ทำให้'],['Result','รถติด']]],
['(S) + Aux + V + Adv','推測のน่าจะ・อาจจะは動詞の前。',[['Aux','น่าจะ'],['V','ถึง'],['Adv','ประมาณสองทุ่มครึ่ง']]],
['S + ถูก + V','行為を受ける人・物がS。ถูก＋Vが続きます。',[['S','เขา'],['Asp','ถูก'],['V','หลอก']]],
['(S) + V + ก่อน + Part','文末のนะなどが相手への態度を添えます。',[['V','พัก'],['Adv','ก่อน'],['Part','นะ']]]
];
structures.push(
['名詞＋ของ＋持ち主','物を先に、誰の物かを後ろに置きます。',[['N','กระเป๋า'],['Link','ของ'],['IO','ผม']]],
['ขอ＋動詞＋場所＋ได้＋疑問の語','自分が何かをする許可を求めます。',[['Part','ขอ'],['V','นั่ง'],['Loc','ตรงนี้'],['Aux','ได้'],['Q','ไหม']]],
['เพิ่ง＋動詞＋目的語／ใกล้จะ＋動詞','起きた直後と、起きる直前を区別します。',[['Asp','เพิ่ง'],['V','กิน'],['O','ข้าว']]],
['อย่า＋動詞／ห้าม＋動詞','相手への制止と、規則による禁止を使い分けます。',[['Part','อย่า'],['V','รีบ']]],
['文＋แต่＋文／ถึง＋条件＋ก็＋結果','対比する二つの内容や、条件に左右されない結果をつなぎます。',[['Aux','อยาก'],['V','ไป'],['Link','แต่'],['Neg','ไม่มี'],['O','เวลา']]],
['状態＋ขึ้น／状態＋ลง','状態語との組み合わせで覚えます。ดีขึ้นは改善、ถูกลงは値下がりを表します。',[['Adj','ดี'],['Adv','ขึ้น'],['Asp','แล้ว']]]
);
const japaneseRoles={...Object.fromEntries(Object.entries(roleInfo).map(([key,value])=>[key,value[0]])),A:'選択肢①',B:'選択肢②'};
function japanesePattern(text){return text.replace(/Q\(O\)/g,'目的語を尋ねる疑問詞').replace(/O₁/g,'目的語①').replace(/O₂/g,'目的語②').replace(/SVO/g,'主語・動詞・目的語の並び').replace(/\b(Clause|Result|Adj|Adv|Loc|Aux|Neg|Num|Clf|Asp|Part|Link|Comp|Cond|Rel|IO|S|V|O|C|T|Q|N|A|B)\b/g,key=>japaneseRoles[key]).replace(/\(主語\)/g,'（主語は省略可）').replace(/名詞名詞/g,'名詞').replace(/動詞動詞/g,'動詞').replace(/状態状態/g,'状態').replace(/時間時間/g,'時間').replace(/目的語目的語/g,'目的語').replace(/受益者受益者/g,'受益者').replace(/説明節修飾節/g,'説明する節')}
// Later chapters write patterns with full-width ＋／; show every pattern with the same spaced separators.
function patternFor(l){return japanesePattern(structures[l.id-1][0]).replace(/\s*[＋+]\s*/g,' + ').replace(/\s*[／]\s*/g,' / ')}
function syntaxPanel(l){const [formula,note,chunks]=structures[l.id-1];return `<section class="syntax-panel"><div class="syntax-heading"><span class="eyebrow">文の組み立て</span><button class="textbtn" onclick="document.querySelector('#role-guide').open=!document.querySelector('#role-guide').open">文の役割 ⓘ</button></div><div class="formula">${esc(japanesePattern(formula))}</div><p class="syntax-note">${japanesePattern(note)}</p><div class="anatomy">${chunks.map(([r,t])=>`<div class="anatomy-chunk role-${r}"><span class="role-tag">${r==='IO'&&l.id===31?'持ち主':roleInfo[r][0]}</span><span class="anatomy-th" lang="th">${t}</span><span class="anatomy-ro">${esc(romanizeThai(t))}</span></div>`).join('')}</div><details id="role-guide"><summary>この文の役割を詳しく見る</summary><div class="role-legend">${[...new Set(chunks.map(x=>x[0]))].map(r=>`<div><b>${r==='IO'&&l.id===31?'持ち主':roleInfo[r][0]}</b><span><small>${r==='IO'&&l.id===31?'誰の物か':roleInfo[r][1]}</small></span></div>`).join('')}</div><p class="subtext">「主語は省略可」は、会話の文脈から誰の話かわかる場合に主語を省けることを示します。日本語の役割名は文の理解のための目安です。</p></details></section>`}
